  $j${"answer": "Write it", "question": "Write the ASK 625 cost paragraph into the operational doc, section 30?", "thread": "W3", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58QmrmH5CmnTHhmk496VRQi1", "press_time": "18:05 CST 2026-11-24", "source": "md_notes_rulings row 557; audit 41802; Wall 11810"}$j$::jsonb,
  'W3',
  $j${"md5": "569edfbe", "path": "ask625/w3/ask625_draft2.md", "note": "draft 2 in the ASK FORM by W3; draft 1 (60b252b0) graded PASS WITH N1, N2 by W1 (Wall 11803); draft 2 applies both and was CONFIRMED by W1 (Wall 11807)", "commit": "93342a80", "source": "md5sum and read by W3; Wall 11799, 11803, 11806, 11807"}$j$::jsonb,
  $j$[{"md5": "569edfbe", "path": "ask625/w3/ask625_draft2.md", "note": "holds the paragraph as written (466 characters with its Why line); there is no other build file", "commit": "93342a80", "source": "md5sum by W3; Wall 11806, 11814"}]$j$::jsonb,
  $j${"how": "insert a new version of operational_doc equal to v146 less the paragraph and its blank line (that text equals v145 fa32021f, W1's readback). The document is versioned; nothing is overwritten.", "rehearsed": "no", "source": "Wall 11814; audit 41802"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1, N2 (draft 1)", "wall_id": 11803, "md5_graded": "60b252b0", "verdict_norm": "PASS", "source": "Wall 11803; fairjudge/w1/g625/grade_ask625_d1.md (commit f40620e7)"}, {"seat": "W1", "verdict": "CONFIRMED (draft 2: N1 and N2 applied and nothing else; 466 characters; BODY LAW 2, 3, 3b, 5, 5b, 7 PASS)", "wall_id": 11807, "md5_graded": "569edfbe", "verdict_norm": "PASS", "source": "Wall 11807 (commit 1afa9ef6)"}]$j$::jsonb,
  ARRAY['569edfbe'], '[41802]'::jsonb,
  $j$[{"kind": "database row (operational_doc)", "name": "the operational document", "before": "v145 fa32021fd8529be62f189ab979f2a6f9, 75,912 characters", "after": "v146 3f9b7aa3f7a25a0519aada4ecd32a98b, 76,380 characters; added in section 30: \"THE COST OF A LIVE RUN. The AAR of every live run states the run's cost in dollars in its RUN part (the_wall_manual §7.4, AAR report). The figure is the run's stored cost (debate_results.run_cost_usd), read by SQL and never estimated. Where the run made calls that have no entry in its stored call costs (debate_results.call_costs), the AAR names those calls and says the cost is higher than the figure. A run that stored no cost reads NOT STORED. (Why: WALL-11796.)\""}]$j$::jsonb,
  $j$[{"name": "W1's checks of the draft by SQL", "result": "placement holds; the word cost stood twice in v145 and neither was a cost rule; the pointer to Wall manual 7.4 resolves to AAR REPORT TO THE OPERATOR and its RUN part; WALL-11796 exists; BODY LAW 2, 3, 3b, 5, 5b and 7 PASS. N1: call_costs is a jsonb column of debate_results, not a table. N2: its sum equals run_cost_usd, so it is no independent check. Both applied in draft 2.", "source": "Wall 11803, 11807"}, {"name": "The write", "result": "one insert of version 146 guarded on the base md5 and on the result md5; run state read first (no launch announced; last debate_results row 17:21 CST, last debate_enforcer_log row 17:38 CST).", "source": "audit 41802; Wall 11810"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (v146 less the 466-character paragraph and one blank line has md5 fa32021f, equal to v145; the paragraph in v146, md5 4b615d03, equals the paragraph in ask625_draft2.md; placement as planned)", "wall_id": 11814, "source": "Wall 11814; fairjudge/w1/g625/readback_625_v146.md (commit 8e95c2ef)"}]$j$::jsonb,
